using System;using System.Xml;using System.Text;using Nini.Config;class Program{static string H(string s){var b=new StringBuilder();foreach(char c in s)b.Append(((int)c).ToString("x4"));return b.ToString();}static void Main(string[] args){if(Array.IndexOf(args,"--disabled")>=0)AppContext.SetSwitch("System.Xml.XmlResolver.IsNetworkingEnabledByDefault",false);if(Array.IndexOf(args,"--default")<0)System.Net.Http.HttpClient.DefaultProxy=new System.Net.WebProxy();string? url;while((url=Console.ReadLine())!=null)try{var source=Array.IndexOf(args,"--startup-reader")>=0?new XmlConfigSource(XmlReader.Create(url,new XmlReaderSettings{DtdProcessing=DtdProcessing.Ignore})):new XmlConfigSource(url);var startup=source.Configs["Startup"];Console.WriteLine(H(startup.GetString("Name"))+":"+H(startup.GetString("Greeting")));}catch(Exception e){Console.Error.WriteLine(e);Console.WriteLine("E:"+e.Message);}}}